      source: [{ doc: "The Adweek Copywriting Handbook (Joseph Sugarman)", section: "Chapter 36 · Writing for Different Media · Catalogs; Flyers: Insert Stuffers, Bounce Backs, and Broadsides · pp. 277–280 (PDF 302–305)", who: "Joseph Sugarman" }],
